{
  "title": "List tables with creation timestamps",
  "description": "For administrative purposes a developer needs to enumerate all tables in a namespace together with the time each table was created. The creation time is stored in the `#metadata#` key with the name `CREATED`. A utility that scans schema keys, loads the schema and fetches the associated metadata provides a ready‑to‑use overview.",
  "code_context": "use {
    async_trait::async_trait,
    gluesql_core::{data::Schema, error::{Error, Result}, store::Store},
    redis::Commands,
    std::cell::RefCell,
    redis::Connection,
};

impl RedisStorage {
    pub async fn list_tables_with_creation(&self) -> Result<Vec<(String, Option<String>)>> {
        let mut result = Vec::new();
        let scan_key = Self::redis_generate_scan_schema_key(&self.namespace);
        let schema_keys: Vec<String> = self
            .conn
            .borrow_mut()
            .scan_match(&scan_key)
            .map(|i| i.collect())
            .map_err(|e| Error::StorageMsg(format!("[RedisStorage] failed to scan schemas: {}", e)))?;
        for sk in schema_keys {
            if let Ok(value) = redis::cmd("GET").arg(&sk).query::<String>(&mut self.conn.borrow_mut()) {
                let schema: Schema = serde_json::from_str(&value)
                    .map_err(|e| Error::StorageMsg(format!("[RedisStorage] failed to deserialize schema: {}", e)))?;
                let meta_key = Self::redis_generate_metadata_key(&self.namespace, &schema.table_name, "CREATED");
                let created = match redis::cmd("GET").arg(&meta_key).query::<String>(&mut self.conn.borrow_mut()) {
                    Ok(v) => Some(v),
                    Err(_) => None,
                };
                result.push((schema.table_name, created));
            }
        }
        Ok(result)
    }
}",
  "function_signature": "fn list_tables_with_creation(&self) -> Result<Vec<(String, Option<String>)>>"
}

